def convert_aht_to_total_time(apps, schema_editor):
    """Convert existing AHT to minutes and back-fill Total time spent = AHT x volume / 60."""
    Forecast = apps.get_model("forecasting", "ManpowerForecast")
    for f in Forecast.objects.all().iterator():
        aht_min = (f.avg_processing_time or Decimal("0")) * TO_MINUTES.get(f.time_unit, Decimal("1"))
